"""Reviewed NL -> SQL pairs for the Keelstone Data Systems demo.

`demo rq-check keelstone --snowflake` executes every pair against DuckDB and
Snowflake and writes build/reviewed-queries.csv in Wisdom's import format.
NL text must not contain commas; SQL uses upper-case identifiers with
double-quoted object names.
"""
from demo_creator.reviewed_queries import Registry

rq = Registry()
add = rq.add

# ---------------------------------------------------------------- lookups / basics
add("Which channel partners do we sell through and what tier are they?",
    'SELECT PARTNER_ID, PARTNER_NAME, PARTNER_TYPE, PARTNER_TIER, PRIMARY_REGION, HQ_COUNTRY FROM "PARTNERS" ORDER BY PARTNER_TIER, PARTNER_NAME')
add("How many customers do we have by region and segment?",
    'SELECT REGION, SEGMENT, COUNT(*) AS CUSTOMER_COUNT FROM "CUSTOMERS" WHERE IS_ACTIVE = TRUE GROUP BY REGION, SEGMENT ORDER BY REGION, SEGMENT')
add("Which products are end of sale or reaching end of support?",
    'SELECT PRODUCT_ID, PRODUCT_NAME, PRODUCT_FAMILY, PRODUCT_LINE, END_OF_SALE_DATE, END_OF_SUPPORT_DATE FROM "PRODUCTS" WHERE END_OF_SALE_DATE IS NOT NULL OR END_OF_SUPPORT_DATE IS NOT NULL ORDER BY END_OF_SUPPORT_DATE, PRODUCT_ID')
add("Show the account team for Brightwater Mutual Insurance.",
    'SELECT C.CUSTOMER_NAME, C.SEGMENT, C.INDUSTRY, C.REGION, C.COUNTRY, P.PARTNER_NAME, R.REP_NAME, R.MANAGER_NAME, C.CUSTOMER_SINCE FROM "CUSTOMERS" AS C JOIN "PARTNERS" AS P ON P.PARTNER_ID = C.PARTNER_ID JOIN "SALES_REPS" AS R ON R.REP_ID = C.REP_ID WHERE C.CUSTOMER_NAME = \'Brightwater Mutual Insurance\'')
add("What is the definition and business owner of each metric in the data dictionary?",
    'SELECT TABLE_NAME, COLUMN_NAME, DESCRIPTION, METRIC_FORMULA, BUSINESS_OWNER, SOURCE_SYSTEM FROM "DATA_DICTIONARY" ORDER BY TABLE_NAME, COLUMN_NAME')

# ---------------------------------------------------------------- ARR (certified) and the Sales Ops gap
add("What is our current ARR?",
    'SELECT ARR_AS_OF_DATE, SUM(ARR) AS ARR, SUM(ACTIVE_CONTRACTS) AS ACTIVE_CONTRACTS FROM "V_ARR_MONTHLY" WHERE ARR_MONTH = DATE \'2026-10-01\' GROUP BY ARR_AS_OF_DATE')
add("What is current ARR by region?",
    'SELECT REGION, SUM(ARR) AS ARR, SUM(ACTIVE_CONTRACTS) AS ACTIVE_CONTRACTS FROM "V_ARR_MONTHLY" WHERE ARR_MONTH = DATE \'2026-10-01\' GROUP BY REGION ORDER BY ARR DESC')
add("Show monthly ARR for the last 12 months by contract type.",
    'SELECT ARR_MONTH, CONTRACT_TYPE, SUM(ARR) AS ARR FROM "V_ARR_MONTHLY" WHERE ARR_MONTH >= DATE \'2025-11-01\' GROUP BY ARR_MONTH, CONTRACT_TYPE ORDER BY ARR_MONTH, CONTRACT_TYPE')
add("How much ARR sits on the KS-7000 family today?",
    'SELECT PRODUCT_FAMILY, CONTRACT_TYPE, SUM(ARR) AS ARR, SUM(ACTIVE_CONTRACTS) AS ACTIVE_CONTRACTS FROM "V_ARR_MONTHLY" WHERE ARR_MONTH = DATE \'2026-10-01\' AND PRODUCT_FAMILY = \'KS-7000\' GROUP BY PRODUCT_FAMILY, CONTRACT_TYPE ORDER BY ARR DESC')
add("Why does the Sales Ops ARR number differ from the Finance ARR number?",
    'SELECT ARR_MONTH, SUM(FINANCE_ARR) AS FINANCE_ARR, SUM(LAPSED_OPEN_ARR) AS LAPSED_OPEN_ARR, SUM(SALESOPS_ARR) AS SALESOPS_ARR, ROUND(SUM(LAPSED_OPEN_ARR) / NULLIF(SUM(FINANCE_ARR), 0), 4) AS GAP_PCT, SUM(LAPSED_OPEN_CONTRACTS) AS LAPSED_OPEN_CONTRACTS FROM "V_ARR_FINANCE_VS_SALESOPS" WHERE ARR_MONTH >= DATE \'2026-04-01\' GROUP BY ARR_MONTH ORDER BY ARR_MONTH')
add("Which region has the biggest gap between Sales Ops ARR and Finance ARR for September 2026?",
    'SELECT REGION, FINANCE_ARR, LAPSED_OPEN_ARR, SALESOPS_ARR, GAP_PCT, LAPSED_OPEN_CONTRACTS FROM "V_ARR_FINANCE_VS_SALESOPS" WHERE ARR_MONTH = DATE \'2026-09-01\' ORDER BY GAP_PCT DESC')
add("Which lapsed contracts is Sales Ops still counting as ARR in Americas East?",
    'SELECT C.CONTRACT_ID, CU.CUSTOMER_NAME, C.CONTRACT_TYPE, P.PRODUCT_NAME, C.END_DATE, C.ANNUAL_VALUE, C.CONTRACT_STATUS, O.STAGE, O.RISK_REASON FROM "CONTRACTS" AS C JOIN "CUSTOMERS" AS CU ON CU.CUSTOMER_ID = C.CUSTOMER_ID JOIN "PRODUCTS" AS P ON P.PRODUCT_ID = C.PRODUCT_ID LEFT JOIN "RENEWAL_OPPORTUNITIES" AS O ON O.CONTRACT_ID = C.CONTRACT_ID WHERE CU.REGION = \'Americas East\' AND C.CONTRACT_STATUS = \'PENDING_RENEWAL\' AND C.END_DATE > DATE \'2025-10-12\' ORDER BY C.ANNUAL_VALUE DESC')

# ---------------------------------------------------------------- renewal performance (hero arc)
add("What is our renewal rate this fiscal year compared with last fiscal year?",
    'SELECT FISCAL_YEAR, SUM(ARR_DUE) AS ARR_DUE, SUM(ARR_RENEWED) AS ARR_RENEWED, SUM(ARR_CHURNED) AS ARR_CHURNED, SUM(ARR_PENDING) AS ARR_PENDING, ROUND(SUM(ARR_RENEWED) / NULLIF(SUM(ARR_DUE), 0), 4) AS RENEWAL_RATE FROM "V_RENEWAL_PERFORMANCE" GROUP BY FISCAL_YEAR ORDER BY FISCAL_YEAR')
add("Which region's renewal rate has dropped the most this fiscal year?",
    """SELECT REGION,
       ROUND(SUM(CASE WHEN FISCAL_YEAR = 'FY26' THEN ARR_RENEWED ELSE 0 END) / NULLIF(SUM(CASE WHEN FISCAL_YEAR = 'FY26' THEN ARR_DUE ELSE 0 END), 0), 4) AS FY26_RENEWAL_RATE,
       ROUND(SUM(CASE WHEN FISCAL_YEAR = 'FY27' THEN ARR_RENEWED ELSE 0 END) / NULLIF(SUM(CASE WHEN FISCAL_YEAR = 'FY27' THEN ARR_DUE ELSE 0 END), 0), 4) AS FY27_RENEWAL_RATE,
       ROUND(SUM(CASE WHEN FISCAL_YEAR = 'FY27' THEN ARR_RENEWED ELSE 0 END) / NULLIF(SUM(CASE WHEN FISCAL_YEAR = 'FY27' THEN ARR_DUE ELSE 0 END), 0)
           - SUM(CASE WHEN FISCAL_YEAR = 'FY26' THEN ARR_RENEWED ELSE 0 END) / NULLIF(SUM(CASE WHEN FISCAL_YEAR = 'FY26' THEN ARR_DUE ELSE 0 END), 0), 4) AS CHANGE_PTS,
       SUM(CASE WHEN FISCAL_YEAR = 'FY27' THEN ARR_DUE ELSE 0 END) AS FY27_ARR_DUE,
       SUM(CASE WHEN FISCAL_YEAR = 'FY27' THEN ARR_PENDING ELSE 0 END) AS FY27_ARR_PENDING
FROM "V_RENEWAL_PERFORMANCE"
GROUP BY REGION
ORDER BY CHANGE_PTS""")
add("Show the Americas East renewal rate by fiscal quarter.",
    'SELECT FISCAL_QUARTER, SUM(ARR_DUE) AS ARR_DUE, SUM(ARR_RENEWED) AS ARR_RENEWED, SUM(ARR_CHURNED) AS ARR_CHURNED, SUM(ARR_PENDING) AS ARR_PENDING, ROUND(SUM(ARR_RENEWED) / NULLIF(SUM(ARR_DUE), 0), 4) AS RENEWAL_RATE FROM "V_RENEWAL_PERFORMANCE" WHERE REGION = \'Americas East\' GROUP BY FISCAL_QUARTER ORDER BY FISCAL_QUARTER')
add("Which product families are renewing worst in Americas East this fiscal year?",
    'SELECT PRODUCT_FAMILY, SUM(ARR_DUE) AS ARR_DUE, SUM(ARR_RENEWED) AS ARR_RENEWED, SUM(ARR_PENDING) AS ARR_PENDING, ROUND(SUM(ARR_RENEWED) / NULLIF(SUM(ARR_DUE), 0), 4) AS RENEWAL_RATE FROM "V_RENEWAL_PERFORMANCE" WHERE REGION = \'Americas East\' AND FISCAL_YEAR = \'FY27\' GROUP BY PRODUCT_FAMILY ORDER BY RENEWAL_RATE')
add("Compare FY27 renewal rate by region and contract type.",
    'SELECT REGION, CONTRACT_TYPE, SUM(ARR_DUE) AS ARR_DUE, ROUND(SUM(ARR_RENEWED) / NULLIF(SUM(ARR_DUE), 0), 4) AS RENEWAL_RATE FROM "V_RENEWAL_PERFORMANCE" WHERE FISCAL_YEAR = \'FY27\' GROUP BY REGION, CONTRACT_TYPE ORDER BY REGION, CONTRACT_TYPE')
add("What is the renewal rate for KS-7000 support contracts by region this fiscal year?",
    'SELECT REGION, SUM(ARR_DUE) AS ARR_DUE, SUM(ARR_RENEWED) AS ARR_RENEWED, ROUND(SUM(ARR_RENEWED) / NULLIF(SUM(ARR_DUE), 0), 4) AS RENEWAL_RATE FROM "V_RENEWAL_PERFORMANCE" WHERE FISCAL_YEAR = \'FY27\' AND PRODUCT_FAMILY = \'KS-7000\' AND CONTRACT_TYPE = \'SUPPORT\' GROUP BY REGION ORDER BY RENEWAL_RATE')

# ---------------------------------------------------------------- renewals in the next 90 days
add("How much ARR is up for renewal in the next 90 days by region and how much is at risk?",
    'SELECT REGION, COUNT(*) AS CONTRACTS, SUM(ANNUAL_VALUE) AS ARR_RENEWING, SUM(CASE WHEN RISK_FLAG = \'AT_RISK\' THEN ANNUAL_VALUE ELSE 0 END) AS ARR_AT_RISK, SUM(CASE WHEN RISK_FLAG = \'AT_RISK\' THEN 1 ELSE 0 END) AS CONTRACTS_AT_RISK FROM "V_RENEWALS_AT_RISK_90D" GROUP BY REGION ORDER BY ARR_AT_RISK DESC')
add("What is driving the at-risk renewals in Americas East?",
    'SELECT RISK_REASON, COUNT(*) AS CONTRACTS, SUM(ANNUAL_VALUE) AS ARR_AT_RISK, COUNT(DISTINCT CUSTOMER_NAME) AS CUSTOMERS FROM "V_RENEWALS_AT_RISK_90D" WHERE REGION = \'Americas East\' AND RISK_FLAG = \'AT_RISK\' GROUP BY RISK_REASON ORDER BY ARR_AT_RISK DESC')
add("Which Americas East customers have the most ARR at risk in the next 90 days?",
    'SELECT CUSTOMER_NAME, SEGMENT, PARTNER_NAME, REP_NAME, COUNT(*) AS CONTRACTS, SUM(ANNUAL_VALUE) AS ARR_AT_RISK, MAX(OPEN_P1_CASES) AS OPEN_P1_CASES, SUM(IS_END_OF_SUPPORT_WITHIN_12M) AS END_OF_SUPPORT_CONTRACTS, MIN(END_DATE) AS FIRST_RENEWAL_DATE FROM "V_RENEWALS_AT_RISK_90D" WHERE REGION = \'Americas East\' AND RISK_FLAG = \'AT_RISK\' GROUP BY CUSTOMER_NAME, SEGMENT, PARTNER_NAME, REP_NAME ORDER BY ARR_AT_RISK DESC LIMIT 15')
add("List the renewals coming up for Brightwater Mutual Insurance.",
    'SELECT CONTRACT_ID, CONTRACT_TYPE, PRODUCT_NAME, PRODUCT_FAMILY, SYSTEM_ID, SYSTEM_MODEL, CURRENT_FIRMWARE, END_DATE, DAYS_TO_RENEWAL, ANNUAL_VALUE, OPPORTUNITY_STAGE, RISK_FLAG, RISK_REASON, COMPETITOR FROM "V_RENEWALS_AT_RISK_90D" WHERE CUSTOMER_NAME = \'Brightwater Mutual Insurance\' ORDER BY END_DATE, ANNUAL_VALUE DESC')
add("How much renewing ARR in the next 90 days is on products reaching end of support?",
    'SELECT REGION, SUM(ANNUAL_VALUE) AS ARR_RENEWING, SUM(CASE WHEN IS_END_OF_SUPPORT_WITHIN_12M = 1 THEN ANNUAL_VALUE ELSE 0 END) AS ARR_ON_END_OF_SUPPORT_PRODUCTS, ROUND(SUM(CASE WHEN IS_END_OF_SUPPORT_WITHIN_12M = 1 THEN ANNUAL_VALUE ELSE 0 END) / NULLIF(SUM(ANNUAL_VALUE), 0), 4) AS SHARE FROM "V_RENEWALS_AT_RISK_90D" GROUP BY REGION ORDER BY ARR_ON_END_OF_SUPPORT_PRODUCTS DESC')
add("Which renewals specialists own the most at-risk ARR?",
    'SELECT REP_NAME, REGION, COUNT(*) AS CONTRACTS_AT_RISK, SUM(ANNUAL_VALUE) AS ARR_AT_RISK FROM "V_RENEWALS_AT_RISK_90D" WHERE RISK_FLAG = \'AT_RISK\' GROUP BY REP_NAME, REGION ORDER BY ARR_AT_RISK DESC LIMIT 10')
add("Which competitors are named on at-risk renewals?",
    'SELECT COMPETITOR, COUNT(*) AS CONTRACTS, SUM(ANNUAL_VALUE) AS ARR_AT_RISK FROM "V_RENEWALS_AT_RISK_90D" WHERE RISK_FLAG = \'AT_RISK\' AND COMPETITOR IS NOT NULL GROUP BY COMPETITOR ORDER BY ARR_AT_RISK DESC')

# ---------------------------------------------------------------- installed base / end of support / firmware
add("How many active systems reach end of support in the next 12 months and where are they?",
    'SELECT REGION, PRODUCT_FAMILY, COUNT(*) AS SYSTEMS, SUM(RAW_CAPACITY_TB) AS CAPACITY_TB, SUM(HAS_ACTIVE_SUPPORT) AS WITH_SUPPORT, COUNT(DISTINCT CUSTOMER_NAME) AS CUSTOMERS FROM "V_INSTALLED_BASE_HEALTH" WHERE IS_END_OF_SUPPORT_WITHIN_12M = 1 GROUP BY REGION, PRODUCT_FAMILY ORDER BY SYSTEMS DESC')
add("Which customers have the largest KS-7000 estates still in production?",
    'SELECT CUSTOMER_NAME, REGION, SEGMENT, COUNT(*) AS KS7000_SYSTEMS, SUM(RAW_CAPACITY_TB) AS CAPACITY_TB, SUM(HAS_ACTIVE_SUPPORT) AS WITH_SUPPORT, SUM(OPEN_P1_CASES) AS OPEN_P1_CASES FROM "V_INSTALLED_BASE_HEALTH" WHERE PRODUCT_FAMILY = \'KS-7000\' GROUP BY CUSTOMER_NAME, REGION, SEGMENT ORDER BY KS7000_SYSTEMS DESC LIMIT 15')
add("What firmware versions is the installed base running by region?",
    'SELECT REGION, CURRENT_FIRMWARE, COUNT(*) AS SYSTEMS FROM "V_INSTALLED_BASE_HEALTH" GROUP BY REGION, CURRENT_FIRMWARE ORDER BY REGION, SYSTEMS DESC')
add("How many systems are still on KeelOS 9.14.2 and how healthy are they?",
    'SELECT REGION, COUNT(*) AS SYSTEMS, ROUND(AVG(LATEST_HEALTH_SCORE), 1) AS AVG_HEALTH_SCORE, SUM(CRITICAL_ALERTS_3M) AS CRITICAL_ALERTS_3M, SUM(OPEN_P1_CASES) AS OPEN_P1_CASES FROM "V_INSTALLED_BASE_HEALTH" WHERE CURRENT_FIRMWARE = \'KeelOS 9.14.2\' GROUP BY REGION ORDER BY SYSTEMS DESC')
add("Which active systems have no support contract today?",
    'SELECT CUSTOMER_NAME, REGION, PARTNER_NAME, PRODUCT_NAME, SYSTEM_ID, INSTALL_DATE, RAW_CAPACITY_TB FROM "V_INSTALLED_BASE_HEALTH" WHERE HAS_ACTIVE_SUPPORT = 0 ORDER BY INSTALL_DATE DESC LIMIT 50')
add("Show the installed base health for Brightwater Mutual Insurance.",
    'SELECT SYSTEM_ID, PRODUCT_NAME, PRODUCT_FAMILY, INSTALL_DATE, SYSTEM_AGE_YEARS, RAW_CAPACITY_TB, WORKLOAD_TYPE, CURRENT_FIRMWARE, LATEST_HEALTH_SCORE, CRITICAL_ALERTS_3M, END_OF_SUPPORT_DATE, HAS_ACTIVE_SUPPORT, SUPPORT_END_DATE, OPEN_P1_CASES FROM "V_INSTALLED_BASE_HEALTH" WHERE CUSTOMER_NAME = \'Brightwater Mutual Insurance\' ORDER BY OPEN_P1_CASES DESC, END_OF_SUPPORT_DATE')
add("Show the monthly health score and critical alerts for system KS7-2025-00002 since May 2026.",
    'SELECT SNAPSHOT_MONTH, FIRMWARE_VERSION, HEALTH_SCORE, CRITICAL_ALERTS, UPTIME_PCT, AVG_LATENCY_MS, CAPACITY_USED_PCT FROM "SYSTEM_TELEMETRY_MONTHLY" WHERE SYSTEM_ID = \'KS7-2025-00002\' AND SNAPSHOT_MONTH >= DATE \'2026-05-01\' ORDER BY SNAPSHOT_MONTH')

# ---------------------------------------------------------------- support cases (unstructured)
add("How many P1 cases on KeelOS 9.14.2 have been opened since July by region?",
    'SELECT REGION, SUM(P1_CASES) AS P1_CASES, SUM(OPEN_CASES) AS STILL_OPEN, SUM(CUSTOMERS_AFFECTED) AS CUSTOMER_MONTHS_AFFECTED FROM "V_SUPPORT_CASE_SUMMARY" WHERE FIRMWARE_VERSION = \'KeelOS 9.14.2\' AND PRIORITY = \'P1\' AND OPENED_MONTH >= DATE \'2026-07-01\' GROUP BY REGION ORDER BY P1_CASES DESC')
add("Show the monthly trend of P1 cases by category this fiscal year.",
    'SELECT OPENED_MONTH, CATEGORY, SUM(P1_CASES) AS P1_CASES FROM "V_SUPPORT_CASE_SUMMARY" WHERE FISCAL_YEAR = \'FY27\' AND PRIORITY = \'P1\' GROUP BY OPENED_MONTH, CATEGORY ORDER BY OPENED_MONTH, CATEGORY')
add("What are customers saying in the P1 case notes about the 9.14.2 upgrade and their renewals?",
    'SELECT SC.CASE_ID, CU.CUSTOMER_NAME, CU.REGION, SC.SYSTEM_ID, SC.OPENED_DATE, SC.CASE_STATUS, SC.ROOT_CAUSE, SC.CSAT_SCORE, SC.CASE_NOTES FROM "SUPPORT_CASES" AS SC JOIN "CUSTOMERS" AS CU ON CU.CUSTOMER_ID = SC.CUSTOMER_ID WHERE SC.PRIORITY = \'P1\' AND SC.FIRMWARE_VERSION = \'KeelOS 9.14.2\' AND SC.CASE_NOTES LIKE \'%renewal%\' ORDER BY SC.OPENED_DATE DESC')
add("Which customers have open P1 cases right now?",
    'SELECT CU.CUSTOMER_NAME, CU.REGION, COUNT(*) AS OPEN_P1_CASES, MIN(SC.OPENED_DATE) AS OLDEST_OPENED, MAX(SC.SUBCATEGORY) AS SUBCATEGORY FROM "SUPPORT_CASES" AS SC JOIN "CUSTOMERS" AS CU ON CU.CUSTOMER_ID = SC.CUSTOMER_ID WHERE SC.PRIORITY = \'P1\' AND SC.CASE_STATUS = \'OPEN\' GROUP BY CU.CUSTOMER_NAME, CU.REGION ORDER BY OPEN_P1_CASES DESC, OLDEST_OPENED')
add("What is the average CSAT and resolution time by priority this fiscal year?",
    'SELECT SC.PRIORITY, COUNT(*) AS CASES, ROUND(AVG(SC.RESOLUTION_HOURS), 1) AS AVG_RESOLUTION_HOURS, ROUND(AVG(SC.CSAT_SCORE), 2) AS AVG_CSAT FROM "SUPPORT_CASES" AS SC WHERE SC.OPENED_DATE >= DATE \'2026-05-01\' AND SC.CASE_STATUS = \'CLOSED\' GROUP BY SC.PRIORITY ORDER BY SC.PRIORITY')
add("Show the support cases for Brightwater Mutual Insurance in the last 90 days.",
    'SELECT SC.CASE_ID, SC.OPENED_DATE, SC.CLOSED_DATE, SC.PRIORITY, SC.CASE_STATUS, SC.CATEGORY, SC.SUBCATEGORY, SC.SYSTEM_ID, SC.FIRMWARE_VERSION, SC.ROOT_CAUSE, SC.CASE_NOTES FROM "SUPPORT_CASES" AS SC JOIN "CUSTOMERS" AS CU ON CU.CUSTOMER_ID = SC.CUSTOMER_ID WHERE CU.CUSTOMER_NAME = \'Brightwater Mutual Insurance\' AND SC.OPENED_DATE >= DATE \'2026-07-14\' ORDER BY SC.OPENED_DATE DESC')

# ---------------------------------------------------------------- cloud
add("How has Keelstone Cloud Volumes consumption grown year over year?",
    """SELECT USAGE_MONTH, SUM(CONSUMED_AMOUNT) AS CONSUMED_AMOUNT, SUM(MONTHLY_COMMIT_AMOUNT) AS COMMIT_AMOUNT, COUNT(DISTINCT CUSTOMER_ID) AS CUSTOMERS
FROM "CLOUD_CONSUMPTION_MONTHLY"
WHERE USAGE_MONTH >= DATE '2025-06-01'
GROUP BY USAGE_MONTH
ORDER BY USAGE_MONTH""")
add("Compare cloud consumption for June to September 2026 with the same months of 2025.",
    """SELECT CASE WHEN USAGE_MONTH >= DATE '2026-06-01' THEN 'Jun-Sep 2026' ELSE 'Jun-Sep 2025' END AS PERIOD,
       SUM(CONSUMED_AMOUNT) AS CONSUMED_AMOUNT, SUM(CONSUMED_TB) AS CONSUMED_TB, COUNT(DISTINCT CUSTOMER_ID) AS CUSTOMERS
FROM "CLOUD_CONSUMPTION_MONTHLY"
WHERE (USAGE_MONTH BETWEEN DATE '2025-06-01' AND DATE '2025-09-01') OR (USAGE_MONTH BETWEEN DATE '2026-06-01' AND DATE '2026-09-01')
GROUP BY CASE WHEN USAGE_MONTH >= DATE '2026-06-01' THEN 'Jun-Sep 2026' ELSE 'Jun-Sep 2025' END
ORDER BY PERIOD""")
add("Which enterprise accounts are consuming less than 60 percent of their cloud commit this fiscal year?",
    'SELECT CUSTOMER_NAME, REGION, PRODUCT_NAME, CLOUD_PROVIDER, MONTHS_REPORTED, COMMIT_AMOUNT, CONSUMED_AMOUNT, UTILIZATION_PCT, COMMIT_AMOUNT - CONSUMED_AMOUNT AS UNCONSUMED_COMMIT FROM "V_CLOUD_COMMIT_UTILIZATION" WHERE FISCAL_YEAR = \'FY27\' AND SEGMENT = \'ENTERPRISE\' AND IS_UNDER_UTILIZED = 1 ORDER BY UNCONSUMED_COMMIT DESC')
add("What is cloud commit utilisation by region and cloud provider this fiscal year?",
    'SELECT REGION, CLOUD_PROVIDER, COUNT(*) AS ACCOUNTS, SUM(COMMIT_AMOUNT) AS COMMIT_AMOUNT, SUM(CONSUMED_AMOUNT) AS CONSUMED_AMOUNT, ROUND(SUM(CONSUMED_AMOUNT) / NULLIF(SUM(COMMIT_AMOUNT), 0), 4) AS UTILIZATION_PCT, SUM(IS_UNDER_UTILIZED) AS UNDER_UTILIZED_ACCOUNTS FROM "V_CLOUD_COMMIT_UTILIZATION" WHERE FISCAL_YEAR = \'FY27\' GROUP BY REGION, CLOUD_PROVIDER ORDER BY REGION, CLOUD_PROVIDER')

# ---------------------------------------------------------------- partners
add("How has support attach rate changed by partner between FY26 and FY27?",
    """SELECT PARTNER_NAME, PARTNER_TIER,
       SUM(CASE WHEN FISCAL_YEAR = 'FY26' THEN SYSTEMS_INSTALLED ELSE 0 END) AS FY26_SYSTEMS,
       ROUND(SUM(CASE WHEN FISCAL_YEAR = 'FY26' THEN SYSTEMS_WITH_SUPPORT ELSE 0 END) / NULLIF(SUM(CASE WHEN FISCAL_YEAR = 'FY26' THEN SYSTEMS_INSTALLED ELSE 0 END), 0), 4) AS FY26_ATTACH_RATE,
       SUM(CASE WHEN FISCAL_YEAR = 'FY27' THEN SYSTEMS_INSTALLED ELSE 0 END) AS FY27_SYSTEMS,
       ROUND(SUM(CASE WHEN FISCAL_YEAR = 'FY27' THEN SYSTEMS_WITH_SUPPORT ELSE 0 END) / NULLIF(SUM(CASE WHEN FISCAL_YEAR = 'FY27' THEN SYSTEMS_INSTALLED ELSE 0 END), 0), 4) AS FY27_ATTACH_RATE
FROM "V_PARTNER_ATTACH_RATE"
WHERE FISCAL_YEAR IN ('FY26', 'FY27')
GROUP BY PARTNER_NAME, PARTNER_TIER
HAVING SUM(CASE WHEN FISCAL_YEAR = 'FY26' THEN SYSTEMS_INSTALLED ELSE 0 END) >= 20
ORDER BY FY27_ATTACH_RATE""")
add("Show Altura Technology Partners attach rate by fiscal quarter.",
    'SELECT FISCAL_QUARTER, SYSTEMS_INSTALLED, SYSTEMS_WITH_SUPPORT, ATTACH_RATE FROM "V_PARTNER_ATTACH_RATE" WHERE PARTNER_NAME = \'Altura Technology Partners\' ORDER BY FISCAL_QUARTER')
add("Which partners booked the most this fiscal year by product line?",
    'SELECT P.PARTNER_NAME, PR.PRODUCT_LINE, COUNT(*) AS ORDER_LINES, SUM(O.NET_AMOUNT) AS BOOKINGS FROM "ORDERS" AS O JOIN "PARTNERS" AS P ON P.PARTNER_ID = O.PARTNER_ID JOIN "PRODUCTS" AS PR ON PR.PRODUCT_ID = O.PRODUCT_ID WHERE O.ORDER_DATE >= DATE \'2026-05-01\' GROUP BY P.PARTNER_NAME, PR.PRODUCT_LINE ORDER BY BOOKINGS DESC LIMIT 20')

# ---------------------------------------------------------------- bookings
add("Show monthly bookings by booking type since May 2025.",
    'SELECT F.MONTH_START_DATE AS ORDER_MONTH, O.BOOKING_TYPE, COUNT(*) AS ORDER_LINES, SUM(O.NET_AMOUNT) AS BOOKINGS FROM "ORDERS" AS O JOIN "FISCAL_CALENDAR" AS F ON F.CALENDAR_DATE = O.ORDER_DATE GROUP BY F.MONTH_START_DATE, O.BOOKING_TYPE ORDER BY ORDER_MONTH, O.BOOKING_TYPE')
add("What were hardware bookings by product family in FY27 so far?",
    'SELECT PR.PRODUCT_FAMILY, COUNT(*) AS SYSTEMS_BOOKED, SUM(O.NET_AMOUNT) AS BOOKINGS, ROUND(AVG(O.DISCOUNT_PCT), 1) AS AVG_DISCOUNT_PCT FROM "ORDERS" AS O JOIN "PRODUCTS" AS PR ON PR.PRODUCT_ID = O.PRODUCT_ID JOIN "FISCAL_CALENDAR" AS F ON F.CALENDAR_DATE = O.ORDER_DATE WHERE PR.PRODUCT_LINE = \'HARDWARE\' AND F.FISCAL_YEAR = \'FY27\' GROUP BY PR.PRODUCT_FAMILY ORDER BY BOOKINGS DESC')

# ---------------------------------------------------------------- the follow-up question itself (3-step chain)
add("Which region's renewal rate has dropped the most this fiscal year and what is driving it and how much ARR is up for renewal there in the next 90 days?",
    """SELECT R.REGION,
       R.FY26_RENEWAL_RATE, R.FY27_RENEWAL_RATE, R.CHANGE_PTS,
       W.ARR_RENEWING_90D, W.ARR_AT_RISK_90D,
       W.ARR_AT_RISK_END_OF_SUPPORT, W.ARR_AT_RISK_OPEN_P1,
       P.P1_CASES_ON_9_14_2_SINCE_JULY
FROM (
    SELECT REGION,
           ROUND(SUM(CASE WHEN FISCAL_YEAR = 'FY26' THEN ARR_RENEWED ELSE 0 END) / NULLIF(SUM(CASE WHEN FISCAL_YEAR = 'FY26' THEN ARR_DUE ELSE 0 END), 0), 4) AS FY26_RENEWAL_RATE,
           ROUND(SUM(CASE WHEN FISCAL_YEAR = 'FY27' THEN ARR_RENEWED ELSE 0 END) / NULLIF(SUM(CASE WHEN FISCAL_YEAR = 'FY27' THEN ARR_DUE ELSE 0 END), 0), 4) AS FY27_RENEWAL_RATE,
           ROUND(SUM(CASE WHEN FISCAL_YEAR = 'FY27' THEN ARR_RENEWED ELSE 0 END) / NULLIF(SUM(CASE WHEN FISCAL_YEAR = 'FY27' THEN ARR_DUE ELSE 0 END), 0)
               - SUM(CASE WHEN FISCAL_YEAR = 'FY26' THEN ARR_RENEWED ELSE 0 END) / NULLIF(SUM(CASE WHEN FISCAL_YEAR = 'FY26' THEN ARR_DUE ELSE 0 END), 0), 4) AS CHANGE_PTS
    FROM "V_RENEWAL_PERFORMANCE"
    GROUP BY REGION
) R
LEFT JOIN (
    SELECT REGION,
           SUM(ANNUAL_VALUE) AS ARR_RENEWING_90D,
           SUM(CASE WHEN RISK_FLAG = 'AT_RISK' THEN ANNUAL_VALUE ELSE 0 END) AS ARR_AT_RISK_90D,
           SUM(CASE WHEN RISK_FLAG = 'AT_RISK' AND RISK_REASON = 'End of support product' THEN ANNUAL_VALUE ELSE 0 END) AS ARR_AT_RISK_END_OF_SUPPORT,
           SUM(CASE WHEN RISK_FLAG = 'AT_RISK' AND RISK_REASON = 'Open P1 case' THEN ANNUAL_VALUE ELSE 0 END) AS ARR_AT_RISK_OPEN_P1
    FROM "V_RENEWALS_AT_RISK_90D"
    GROUP BY REGION
) W ON W.REGION = R.REGION
LEFT JOIN (
    SELECT REGION, SUM(P1_CASES) AS P1_CASES_ON_9_14_2_SINCE_JULY
    FROM "V_SUPPORT_CASE_SUMMARY"
    WHERE FIRMWARE_VERSION = 'KeelOS 9.14.2' AND PRIORITY = 'P1' AND OPENED_MONTH >= DATE '2026-07-01'
    GROUP BY REGION
) P ON P.REGION = R.REGION
ORDER BY R.CHANGE_PTS""")
